/**
 * Tutorial catalogue, schema v2: the /tutorials hub, one guide page per published
 * tutorial at /tutorials/<slug>/ (routes generated by plugins/tutorial-pages), and the
 * shared TutorialVideo component.
 *
 * The data lives in tutorials.json so plugins/tutorial-pages and scripts/verify-tutorials.mjs
 * can read it without a TypeScript toolchain. Only tutorials with real, first-party media are
 * in `tutorials`; recordings that do not exist yet stay in `planned` and never get a page.
 * Per-guide extras (agent notes, terminal captures, chapter notes) live in tutorial-extras.json,
 * keyed by slug, and are merged in by toTutorial.
 */
import data from './tutorials.json';
import extrasData from './tutorial-extras.json';
import {isHostedMedia, mediaUrl} from '../lib/media';

export type AgentId = 'claude-code' | 'codex' | 'opencode' | 'antigravity' | 'grok' | 'cursor';
/** `multi`: shows several agents (see agentsShown). `any`: works the same with every agent. */
export type TutorialAgent = AgentId | 'multi' | 'any';
export type TutorialProduct = 'cli' | 'specwithcode';
export type CatalogueProduct = TutorialProduct | 'verified-skill';
export type TutorialStatus = 'published';

export interface TutorialChapter {
  /** Seconds from the start of the video. */
  start: number;
  title: string;
}

export interface TutorialMedia {
  /** First-party path under static/. */
  src: string;
  poster: string;
  captionsVtt: string;
  /** True when the captions are not burned into the video, so the track starts on. */
  captionsOn?: boolean;
  /** True when captions are burned into the picture; the VTT then serves search and transcripts only. */
  captionsBurnedIn?: boolean;
  audio: 'silent' | 'narrated';
  durationSeconds: number;
  /** ISO date (YYYY-MM-DD) the file was added. */
  uploadDate: string;
  /**
   * When spec-weave.com first served this video: the completion time of the first
   * successful deploy-docs run containing the commit that added it. Null until known;
   * the video then stays out of the structured data.
   */
  publishedAt: string | null;
  chapters: TutorialChapter[];
}

/** A real terminal run from video/tutorials/<folder>/captures/, shown on the guide page. */
export interface CaptureRef {
  /** Repository-relative path, under video/tutorials/. */
  file: string;
  label: string;
}

/** A capture as plugins/tutorial-pages passes it to the page: trimmed, already redacted. */
export interface TranscriptCapture {
  label: string;
  command: string;
  exitCode: number | null;
  stdout: string;
  /** True when stdout was cut to the first lines. */
  truncated: boolean;
  capturedAt: string;
}

/** A correction shown under one transcript chapter, for recordings that predate the current app. */
export interface ChapterNote {
  /** Start of the chapter it belongs to, in seconds; must match a chapter start. */
  start: number;
  text: string;
  to?: string;
  label?: string;
}

/** Optional guide content kept outside tutorials.json, keyed by slug. */
export interface TutorialExtras {
  /** What differs for this agent, from the episode's SCRIPT.md sources and recording notes. */
  agentNotes?: string[];
  captures?: CaptureRef[];
  chapterNotes?: ChapterNote[];
  /** ISO date this guide's content last changed; the sitemap's lastmod. */
  updatedAt?: string;
}

export interface TutorialAction {
  label: string;
  to: string;
}

/** One tutorial exactly as tutorials.json stores it. */
export interface TutorialEntry {
  slug: string;
  product: TutorialProduct;
  /** An imperative task, such as "Hand off from Claude Code to Codex". */
  title: string;
  seoTitle: string;
  summary: string;
  /** Meta description, at most 155 characters, for tutorials whose summary is longer than 160. */
  seoDescription?: string;
  /** One sentence: what you have at the end. */
  outcome: string;
  prerequisites: string[];
  /** The version shown in the recording, or null when it is not on record. */
  testedOn: string | null;
  agent: TutorialAgent;
  agentsShown: AgentId[];
  video: TutorialMedia;
  /** Full sentences; exact commands in backticks, exact UI labels as written in the app. */
  steps: string[];
  /** `captions`: the guide page prints a transcript built from the caption file. */
  transcript: 'captions' | null;
  note: string;
  action: TutorialAction | null;
  /** Site path of the written reference that goes with the video. */
  guide: string | null;
  related: string[];
}

/**
 * A catalogue entry plus the flat media fields older callers read (`src`, `poster`,
 * `chapters`, ...). Both views describe the same file.
 */
export interface Tutorial extends TutorialEntry, TutorialExtras, Omit<TutorialMedia, 'publishedAt'> {
  status: TutorialStatus;
  publishedAt: string | null;
}

export interface PlannedTutorial {
  slug: string;
  product: CatalogueProduct;
  title: string;
  outcome: string;
  beats: string[];
  targetSeconds: number;
  agent?: AgentId;
  /** Published slug this recording will replace once it ships. */
  replaces?: string;
}

export interface LearningPath {
  id: string;
  product: CatalogueProduct;
  title: string;
  summary: string;
  /** Hub on another site that owns this path, when it is not spec-weave.com. */
  url?: string;
  /** Published or planned slugs, in order. */
  steps: string[];
}

export interface TranscriptSection {
  start: number;
  title: string;
  text: string;
}

interface Catalogue {
  schemaVersion: 2;
  requiredAgents: AgentId[];
  tutorials: TutorialEntry[];
  planned: PlannedTutorial[];
  paths: LearningPath[];
}

const catalogue = data as unknown as Catalogue;
const extras = extrasData as unknown as {schemaVersion: 1; guidesUpdatedAt: string; guides: Record<string, TutorialExtras>};

export const AGENTS: ReadonlyArray<{id: AgentId; label: string}> = [
  {id: 'claude-code', label: 'Claude Code'},
  {id: 'codex', label: 'Codex'},
  {id: 'opencode', label: 'OpenCode'},
  {id: 'antigravity', label: 'Antigravity'},
  {id: 'grok', label: 'Grok'},
  {id: 'cursor', label: 'Cursor'},
];

export const PRODUCTS: ReadonlyArray<{id: CatalogueProduct; label: string}> = [
  {id: 'cli', label: 'SpecWeave CLI'},
  {id: 'specwithcode', label: 'SpecWithCode'},
  {id: 'verified-skill', label: 'Verified Skill'},
];

export function toTutorial(entry: TutorialEntry): Tutorial {
  return {...entry, ...extras.guides[entry.slug], ...entry.video, status: 'published'};
}

export const TUTORIALS: readonly Tutorial[] = catalogue.tutorials.map(toTutorial);
export const PLANNED: readonly PlannedTutorial[] = catalogue.planned;
export const PATHS: readonly LearningPath[] = catalogue.paths;
export const REQUIRED_AGENTS: readonly AgentId[] = catalogue.requiredAgents;

export function productLabel(product: CatalogueProduct): string {
  return PRODUCTS.find(p => p.id === product)?.label ?? product;
}

export function agentLabel(tutorial: Pick<Tutorial, 'agent' | 'agentsShown'>): string {
  if (tutorial.agent === 'any') return 'Any agent';
  if (tutorial.agent === 'multi') {
    const names = tutorial.agentsShown.map(id => AGENTS.find(a => a.id === id)?.label ?? id);
    return names.length ? names.join(' and ') : 'Several agents';
  }
  return AGENTS.find(a => a.id === tutorial.agent)?.label ?? tutorial.agent;
}

/**
 * True when the recording shows the current generation of the product: SpecWeave 3.x or
 * SpecWithCode 1.x. Older recordings (SpecWithCode 0.2.x, or no version on record) still
 * teach the task but show an older interface.
 */
export function isCurrentRecording(t: Pick<Tutorial, 'testedOn'>): boolean {
  return /^(SpecWeave 3\.|SpecWithCode 1\.)/.test(t.testedOn ?? '');
}

/** Current recordings first; catalogue order within each group. */
export function byRecency<T extends Pick<Tutorial, 'testedOn'>>(list: readonly T[]): T[] {
  return [...list.filter(isCurrentRecording), ...list.filter(t => !isCurrentRecording(t))];
}

/** Hub filter: one product, or everything. */
export type ProductFilter = TutorialProduct | 'all';

export function matchesProduct(tutorial: Pick<Tutorial, 'product'>, filter: ProductFilter): boolean {
  return filter === 'all' || tutorial.product === filter;
}

/** Case-insensitive match on every word of the query against title, summary, outcome, agent and chapters. */
export function matchesQuery(tutorial: Tutorial, query: string): boolean {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  const haystack = [
    tutorial.title,
    tutorial.summary,
    tutorial.outcome,
    agentLabel(tutorial),
    productLabel(tutorial.product),
    ...tutorial.chapters.map(c => c.title),
  ].join(' ').toLowerCase();
  return words.every(word => haystack.includes(word));
}

export function getTutorial(slug: string): Tutorial | undefined {
  return TUTORIALS.find(t => t.slug === slug);
}

export function getPlanned(slug: string): PlannedTutorial | undefined {
  return PLANNED.find(t => t.slug === slug);
}

/** Path of a guide page on this site, with the trailing slash the site uses. */
export function guidePath(slug: string): string {
  return `/tutorials/${slug}/`;
}

/** Absolute guide URL, optionally at a time offset (chapter links in the structured data). */
export function tutorialUrl(origin: string, slug: string, start?: number): string {
  const t = start ? `?t=${Math.floor(start)}` : '';
  return `${origin}${guidePath(slug)}${t}`;
}

/** The published and planned steps of a learning path, in order. Unknown slugs are dropped. */
export function resolvePath(path: LearningPath): {published: Tutorial[]; planned: PlannedTutorial[]} {
  const published: Tutorial[] = [];
  const planned: PlannedTutorial[] = [];
  for (const slug of path.steps) {
    const tutorial = getTutorial(slug);
    if (tutorial) published.push(tutorial);
    else {
      const upcoming = getPlanned(slug);
      if (upcoming) planned.push(upcoming);
    }
  }
  return {published, planned};
}

/**
 * How many other guides link to this one: related lists of other published tutorials, plus
 * learning paths hosted on this site. Every published guide should have at least one.
 */
export function inboundLinks(slug: string): number {
  const related = TUTORIALS.filter(t => t.slug !== slug && t.related.includes(slug)).length;
  return related + pathsFor(slug).length;
}

/** Learning paths on this site that include the tutorial. */
export function pathsFor(slug: string): LearningPath[] {
  return PATHS.filter(p => !p.url && p.steps.includes(slug));
}

/** Start offset in seconds from `?t=` or `#t=`, as chapter links and old deep links carry it. */
export function parseStart(search: string, hash: string): number | undefined {
  const raw = new URLSearchParams(search).get('t') ?? new URLSearchParams(hash.replace(/^#/, '')).get('t');
  if (raw === null) return undefined;
  const t = Number(raw);
  return Number.isFinite(t) && t > 0 ? t : undefined;
}

/** Old hub deep links (`/tutorials/?v=<slug>&t=<s>`) now open the guide page. */
export function legacyRedirect(search: string): string | null {
  const slug = new URLSearchParams(search).get('v');
  if (!slug || !getTutorial(slug)) return null;
  const t = parseStart(search, '');
  return `${guidePath(slug)}${t ? `#t=${Math.floor(t)}` : ''}`;
}

/** 61 -> "1:01", 89.9 -> "1:29" (whole seconds, as native players show it). */
export function formatDuration(seconds: number): string {
  const total = Math.floor(seconds);
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}

/** 61 -> "PT1M1S" (ISO 8601, as schema.org VideoObject expects). */
export function isoDuration(seconds: number): string {
  const total = Math.round(seconds);
  const m = Math.floor(total / 60), s = total % 60;
  return `PT${m ? `${m}M` : ''}${s || !m ? `${s}S` : ''}`;
}

/** "2026-10-12" -> "12 October 2026", the brand book's date format. */
export function formatDate(isoDate: string): string {
  const [y, m, d] = isoDate.slice(0, 10).split('-').map(Number);
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  return `${d} ${months[m - 1]} ${y}`;
}

const publisher = (origin: string) => ({'@type': 'Organization', name: 'SpecWeave', url: origin});

/** The caption transcript as one text, for the VideoObject's `transcript`. */
export function transcriptText(transcript: readonly TranscriptSection[]): string {
  return transcript.map(s => s.text).join(' ');
}

/**
 * schema.org VideoObject for one tutorial, with Clip chapters; null until it has a first public
 * time. There is no embedUrl: the guide page is not a player, and contentUrl names the file on R2.
 */
export function buildVideoObject(t: Tutorial, origin: string, transcript: readonly TranscriptSection[] = []) {
  if (!t.publishedAt) return null;
  const duration = t.durationSeconds;
  const text = transcriptText(transcript);
  return {
    '@type': 'VideoObject',
    '@id': `${tutorialUrl(origin, t.slug)}#video`,
    name: t.title,
    description: t.seoDescription ?? t.summary,
    thumbnailUrl: [`${origin}${t.poster}`],
    uploadDate: t.publishedAt,
    duration: isoDuration(duration),
    contentUrl: isHostedMedia(t.src) ? mediaUrl(t.src) : `${origin}${t.src}`,
    ...(text ? {transcript: text} : {}),
    inLanguage: 'en',
    isAccessibleForFree: true,
    publisher: publisher(origin),
    hasPart: t.chapters.map((c, i) => ({
      '@type': 'Clip',
      name: c.title,
      startOffset: Math.floor(c.start),
      endOffset: Math.floor(t.chapters[i + 1]?.start ?? duration),
      url: tutorialUrl(origin, t.slug, c.start),
    })),
  };
}

type VideoObject = NonNullable<ReturnType<typeof buildVideoObject>>;

/** VideoObject list for the given tutorials (those with a first public time). */
export function buildVideoJsonLd(tutorials: readonly Tutorial[], origin: string) {
  const videos = tutorials.map(t => buildVideoObject(t, origin)).filter((v): v is VideoObject => v !== null);
  return {'@context': 'https://schema.org', '@graph': videos};
}

function breadcrumbs(items: Array<{name: string; url: string}>) {
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, i) => ({'@type': 'ListItem', position: i + 1, name: item.name, item: item.url})),
  };
}

/** Guide page: a TechArticle carrying its VideoObject, plus breadcrumbs. */
export function buildGuideJsonLd(t: Tutorial, origin: string, transcript: readonly TranscriptSection[] = []) {
  const url = tutorialUrl(origin, t.slug);
  const video = buildVideoObject(t, origin, transcript);
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'TechArticle',
        '@id': `${url}#article`,
        headline: t.title,
        description: t.outcome,
        url,
        mainEntityOfPage: url,
        inLanguage: 'en',
        image: `${origin}${t.poster}`,
        ...(t.publishedAt ? {datePublished: t.publishedAt} : {}),
        about: {'@type': 'SoftwareApplication', name: productLabel(t.product)},
        author: publisher(origin),
        publisher: publisher(origin),
        ...(video ? {video} : {}),
      },
      breadcrumbs([
        {name: 'Home', url: `${origin}/`},
        {name: 'Tutorials', url: `${origin}/tutorials/`},
        {name: t.title, url},
      ]),
    ],
  };
}

/** Hub page: the list of guide pages, plus breadcrumbs. Each video is described on its own guide page. */
export function buildHubJsonLd(tutorials: readonly Tutorial[], origin: string) {
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'CollectionPage',
        '@id': `${origin}/tutorials/#page`,
        url: `${origin}/tutorials/`,
        name: 'Tutorials',
        mainEntity: {
          '@type': 'ItemList',
          itemListElement: tutorials.map((t, i) => ({'@type': 'ListItem', position: i + 1, url: tutorialUrl(origin, t.slug), name: t.title})),
        },
      },
      breadcrumbs([
        {name: 'Home', url: `${origin}/`},
        {name: 'Tutorials', url: `${origin}/tutorials/`},
      ]),
    ],
  };
}
